-- ---date:20260526-----for:【QQYUN-15518】comment是达梦数据库保留关键字，列名改为remark；body列名称修改 --
ALTER TABLE `open_api`
    CHANGE COLUMN `comment` `remarks` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '白名单备注说明' AFTER `white_list`,
    CHANGE COLUMN `body` `request_body` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '请求体内容' AFTER `remarks`;


-- ---date:20260526-----for:【QQYUN-15501】openapi提供无接口调用日志监控功能 --
ALTER TABLE `open_api_log`
ADD COLUMN `caller_ak`      varchar(100)  NULL DEFAULT NULL COMMENT '调用者AK'                       AFTER `call_auth_id`,
ADD COLUMN `request_method` varchar(10)   NULL DEFAULT NULL COMMENT 'HTTP请求方式'                   AFTER `caller_ak`,
ADD COLUMN `request_path`   varchar(500)  NULL DEFAULT NULL COMMENT '请求路径'                       AFTER `request_method`,
ADD COLUMN `ip`      varchar(50)   NULL DEFAULT NULL COMMENT '来源IP'                         AFTER `request_path`,
ADD COLUMN `request_params` varchar(600)  NULL DEFAULT NULL COMMENT '请求参数摘要（Query String）'   AFTER `ip`,
ADD COLUMN `response_code`  int(6)        NULL DEFAULT NULL COMMENT '响应状态码'                     AFTER `request_params`,
ADD COLUMN `error_msg`      varchar(500)  NULL DEFAULT NULL COMMENT '失败原因（认证/授权异常描述）'  AFTER `response_code`;


