REPLACE INTO `onl_drag_page` (`id`, `name`, `path`, `background_color`, `background_image`, `design_type`, `theme`, `style`, `cover_url`, `des_json`, `template`, `protection_code`, `type`, `iz_template`, `create_by`, `create_time`, `update_by`, `update_time`, `low_app_id`, `tenant_id`, `update_count`, `visits_num`, `del_flag`) VALUES ('1228912868522151936','b','/drag/page/view/1228912868522151936','#1E0047','/img/bg/bg4.png',100,'dark','bigScreen',NULL,'{\"width\":1920,\"height\":1080,\"waterMark\":{\"show\":false,\"content\":\"\",\"fontSize\":12,\"color\":\"#ffffff\",\"angle\":45},\"sysDefColor\":[{\"color\":\"#1e90ff\",\"color1\":\"#1e90ff\"},{\"color\":\"#90ee90\",\"color1\":\"#90ee90\"},{\"color\":\"#00ced1\",\"color1\":\"#00ced1\"},{\"color\":\"#e2bd84\",\"color1\":\"#e2bd84\"},{\"color\":\"#7a90e0\",\"color1\":\"#7a90e0\"},{\"color\":\"#3ba272\",\"color1\":\"#3ba272\"},{\"color\":\"#2be7ff\",\"color1\":\"#2be7ff\"},{\"color\":\"#0a8ada\",\"color1\":\"#0a8ada\"},{\"color\":\"#ffd700\",\"color1\":\"#ffd700\"}],\"layoutMode\":\"fullScreen\",\"autoRefresh\":{\"enabled\":false,\"time\":\"03:00\"}}','[{\"component\":\"JCustomEchart\",\"visible\":true,\"w\":612,\"x\":1198,\"h\":463,\"i\":\"de34e973-e32d-406b-80a8-3235deac7712\",\"y\":609,\"orderNum\":759,\"componentName\":\"自定义HTML\",\"pageCompId\":\"1229647312761606144\"},{\"component\":\"JArea\",\"visible\":true,\"w\":450,\"x\":641,\"h\":300,\"i\":\"30e57f75-4e77-4c14-a5cc-5debe8aa0067\",\"y\":655,\"orderNum\":0,\"componentName\":\"面积图\",\"pageCompId\":\"1229647312782577664\",\"key\":\"e04ba5f6-e873-4642-8ad6-1bd7bade48f1\"},{\"component\":\"JCustomEchart\",\"visible\":true,\"w\":450,\"x\":1274,\"h\":300,\"i\":\"a2e44d10-1988-4e23-80ea-bdbfa7330c0f\",\"y\":267,\"orderNum\":0,\"componentName\":\"自定义HTML\",\"pageCompId\":\"1229647312795160576\",\"key\":\"0130bd23-5158-482e-91f2-9280f28ece57\"},{\"component\":\"JPie\",\"visible\":true,\"w\":450,\"x\":1270,\"h\":300,\"i\":\"256250e0-a7ba-4157-83c0-d0f7bd3d5b9a\",\"y\":3,\"orderNum\":0,\"componentName\":\"饼图\",\"pageCompId\":\"1229647312807743488\",\"key\":\"2b55cdd9-810d-4b30-8abb-3623bb321866\"},{\"component\":\"JCustomEchart\",\"visible\":true,\"w\":450,\"x\":702,\"h\":300,\"i\":\"6fbdc90e-178c-462b-81dc-f720766d7fb8\",\"y\":22,\"orderNum\":0,\"componentName\":\"自定义HTML（钻取）\",\"pageCompId\":\"1229647312816132096\",\"key\":\"5ad23e84-d2ae-425d-b72c-84f6b39c8df8\"},{\"component\":\"JBar\",\"visible\":true,\"w\":550,\"x\":4,\"h\":364,\"i\":\"a2e94405-c1e8-4fbf-8d49-3190dd0ab978\",\"y\":376,\"orderNum\":639,\"componentName\":\"基础柱形图\",\"pageCompId\":\"1229647312824520704\",\"key\":\"89a5bf1e-41e8-46d9-ae0e-1e89c6c334aa\"},{\"component\":\"JCustomEchart\",\"visible\":true,\"w\":472,\"x\":5,\"h\":302,\"i\":\"286e5f11-2d01-4951-8c10-07c39df0a425\",\"y\":27,\"orderNum\":0,\"componentName\":\"自定义HTML （联动）\",\"pageCompId\":\"1229647312841297920\",\"key\":\"fae49f54-caeb-4233-89a2-d554ec52f919\"},{\"component\":\"JDragBorder\",\"visible\":true,\"w\":1311,\"x\":565,\"h\":483,\"i\":\"es-drager-1782265149014-2\",\"y\":593,\"orderNum\":0,\"componentName\":\"边框12\",\"pageCompId\":\"1229647312853880832\",\"key\":\"3786623f-5c6f-49ca-8724-233e82597c5f\"},{\"component\":\"JDragBorder\",\"visible\":true,\"w\":546,\"x\":1240,\"h\":586,\"i\":\"es-drager-1782265136343-1\",\"y\":-2,\"orderNum\":0,\"componentName\":\"边框12\",\"pageCompId\":\"1229647312866463744\",\"key\":\"5fb66e57-9795-4c27-9e3e-93d88f74103f\"},{\"component\":\"JDragBorder\",\"visible\":true,\"w\":533,\"x\":0,\"h\":759,\"i\":\"9f243d95-c8db-4aa4-8517-e0d400072324\",\"y\":0,\"orderNum\":0,\"componentName\":\"边框12\",\"pageCompId\":\"1229647312879046656\",\"key\":\"448d7433-e352-4521-872e-0ca6ebc77970\"}]','','1023810558598676480','0','admin','2026-06-22 13:47:50','admin','2026-06-24 14:26:15',NULL,1000,2,110,0);

-- ---------- 2. 页面组件 onl_drag_page_comp (10 行) ----------
REPLACE INTO `onl_drag_page_comp` (`id`, `parent_id`, `page_Id`, `comp_id`, `component`, `config`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES ('1229647312761606144',NULL,'1228912868522151936',NULL,'JCustomEchart','{\"borderColor\":\"#FFFFFF00\",\"dataType\":1,\"h\":300,\"customEchartOption\":\"\",\"url\":\"\",\"timeOut\":0,\"size\":{\"width\":612.0555555555555,\"height\":463},\"actionConfig\":{\"operateType\":\"modal\",\"modalName\":\"\",\"url\":\"\"},\"background\":\"#FFFFFF00\",\"w\":450,\"customRenderType\":\"html\",\"customHtmlContent\":\"<!DOCTYPE html>\\n<html><head><meta charset=\\\"UTF-8\\\">\\n<style>\\n  body { background: transparent; padding: 16px; color:#fff; font-family:\'Microsoft YaHei\'; }\\n  .group { margin-bottom: 12px; }\\n  .label { font-size: 12px; color: #8899aa; margin-bottom: 6px; }\\n  .row { display: flex; gap: 8px; flex-wrap: wrap; }\\n  button {\\n    padding: 6px 14px; border-radius: 4px; cursor: pointer; border: 1px solid rgba(24,144,255,.4);\\n    background: rgba(24,144,255,.2); color: #fff; font-size: 13px;\\n  }\\n  button:hover { background: rgba(24,144,255,.5); }\\n  button.warn { border-color: rgba(255,170,80,.5); background: rgba(255,170,80,.2); }\\n  button.warn:hover { background: rgba(255,170,80,.5); }\\n  button.success { border-color: rgba(80,200,160,.5); background: rgba(80,200,160,.2); }\\n  button.success:hover { background: rgba(80,200,160,.5); }\\n  pre { background: rgba(0,0,0,.3); padding: 10px; border-radius: 4px; font-size: 11px; max-height: 180px; overflow: auto; margin-top: 10px; }\\n  input { width: 100%; padding: 6px; margin-bottom: 12px; background: rgba(0,0,0,.3); border: 1px solid rgba(255,255,255,.2); color: #fff; border-radius: 4px; }\\n</style></head>\\n<body>\\n  <!-- 默认填好面积图 id；想操控别的组件改这里即可 -->\\n  <input type=\\\"text\\\" id=\\\"targetId\\\" value=\\\"30e57f75-4e77-4c14-a5cc-5debe8aa0067\\\" placeholder=\\\"目标组件 id\\\" />\\n\\n  <div class=\\\"group\\\">\\n    <div class=\\\"label\\\">显隐</div>\\n    <div class=\\\"row\\\">\\n      <button onclick=\\\"hide()\\\">隐藏</button>\\n      <button onclick=\\\"show()\\\">显示</button>\\n    </div>\\n  </div>\\n\\n  <div class=\\\"group\\\">\\n    <div class=\\\"label\\\">位置 / 尺寸</div>\\n    <div class=\\\"row\\\">\\n      <button onclick=\\\"move()\\\">移到 (700, 500)</button>\\n      <button onclick=\\\"resize()\\\">尺寸 600x400</button>\\n    </div>\\n  </div>\\n\\n  <div class=\\\"group\\\">\\n    <div class=\\\"label\\\">配置（深合并 config）</div>\\n    <div class=\\\"row\\\">\\n      <button onclick=\\\"setTitle()\\\">改标题</button>\\n      <button onclick=\\\"batchUpdate()\\\">一次改多项</button>\\n    </div>\\n  </div>\\n\\n  <div class=\\\"group\\\">\\n    <div class=\\\"label\\\">数据 / 主题（新增）</div>\\n    <div class=\\\"row\\\">\\n      <button class=\\\"success\\\" onclick=\\\"randomData()\\\">随机数据</button>\\n      <button class=\\\"success\\\" onclick=\\\"nextTheme()\\\">切换主题色</button>\\n      <button class=\\\"warn\\\" onclick=\\\"reload()\\\">重置为初始数据</button>\\n    </div>\\n  </div>\\n\\n  <div class=\\\"group\\\">\\n    <div class=\\\"label\\\">读取（get）</div>\\n    <div class=\\\"row\\\">\\n      <button onclick=\\\"readState()\\\">读取目标状态</button>\\n    </div>\\n    <pre id=\\\"output\\\">点击「读取目标状态」查看 JLink.get 返回...</pre>\\n  </div>\\n\\n  <script>\\n    function id() { return document.getElementById(\'targetId\').value.trim(); }\\n\\n    // ===== 原有 ===== //\\n    function hide()   { JLink.hide(id()); }\\n    function show()   { JLink.show(id()); }\\n    function move()   { JLink.move(id(), 700, 500); }\\n    function resize() { JLink.resize(id(), 600, 400); }\\n\\n    function setTitle() {\\n      JLink.setConfig(id(), {\\n        option: { title: { text: \'新标题 @\' + new Date().toLocaleTimeString() } }\\n      });\\n    }\\n\\n    function batchUpdate() {\\n      JLink.update(id(), {\\n        visible: true,\\n        x: 640, y: 520,\\n        w: 550, h: 380,\\n        config: { option: { title: { text: \'批量更新\' } } }\\n      });\\n    }\\n\\n    async function readState() {\\n      try {\\n        const comp = await JLink.get(id());\\n        document.getElementById(\'output\').textContent = JSON.stringify(comp, null, 2);\\n      } catch (e) {\\n        document.getElementById(\'output\').textContent = \'错误：\' + e.message;\\n      }\\n    }\\n\\n    // ===== 新增：随机数据 ===== //\\n    function randomData() {\\n      var brands = [\'苹果\', \'香蕉\', \'梨子\', \'橘子\', \'榴莲\'];\\n      var rows = brands.map(function (b) {\\n        return { name: b, value: Math.floor(Math.random() * 900 + 100) };\\n      });\\n      JLink.setData(id(), rows);\\n    }\\n\\n    // ===== 新增：切换主题色（点一下换一组配色） ===== //\\n    var THEMES = [\\n      [{color:\'#5470c6\', color1:\'#5470c6\'}, {color:\'#91cc75\', color1:\'#91cc75\'}, {color:\'#fac858\', color1:\'#fac858\'}, {color:\'#ee6666\', color1:\'#ee6666\'}, {color:\'#73c0de\', color1:\'#73c0de\'}],   // 经典\\n      [{color:\'#ff7e67\', color1:\'#ff7e67\'}, {color:\'#feca57\', color1:\'#feca57\'}, {color:\'#48dbfb\', color1:\'#48dbfb\'}, {color:\'#1dd1a1\', color1:\'#1dd1a1\'}, {color:\'#5f27cd\', color1:\'#5f27cd\'}],   // 鲜亮\\n      [{color:\'#1abc9c\', color1:\'#1abc9c\'}, {color:\'#3498db\', color1:\'#3498db\'}, {color:\'#9b59b6\', color1:\'#9b59b6\'}, {color:\'#34495e\', color1:\'#34495e\'}, {color:\'#16a085\', color1:\'#16a085\'}],   // 冷调\\n      [{color:\'#e74c3c\', color1:\'#e74c3c\'}, {color:\'#f39c12\', color1:\'#f39c12\'}, {color:\'#d35400\', color1:\'#d35400\'}, {color:\'#c0392b\', color1:\'#c0392b\'}, {color:\'#7f8c8d\', color1:\'#7f8c8d\'}],   // 暖橙\\n      [{color:\'#26de81\', color1:\'#26de81\'}, {color:\'#2bcbba\', color1:\'#2bcbba\'}, {color:\'#45aaf2\', color1:\'#45aaf2\'}, {color:\'#a55eea\', color1:\'#a55eea\'}, {color:\'#fd9644\', color1:\'#fd9644\'}]    // 清新\\n    ];\\n    var themeIdx = 0;\\n    function nextTheme() {\\n      themeIdx = (themeIdx + 1) % THEMES.length;\\n      JLink.setConfig(id(), {\\n        option: { customColor: THEMES[themeIdx] }\\n      });\\n    }\\n\\n    // ===== 新增：重置数据（重新查询数据集） ===== //\\n    function reload() { JLink.reload(id()); }\\n  </script>\\n</body></html>\",\"option\":{\"title\":{\"textAlign\":\"left\",\"show\":false,\"text\":\"\"},\"card\":{\"rightHref\":\"\",\"size\":\"default\",\"extra\":\"\",\"title\":\"\"}}}','admin','2026-06-24 14:26:15',NULL,NULL);
REPLACE INTO `onl_drag_page_comp` (`id`, `parent_id`, `page_Id`, `comp_id`, `component`, `config`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES ('1229647312782577664',NULL,'1228912868522151936',NULL,'JArea','{\"borderColor\":\"#FFFFFF00\",\"paramOption\":[],\"dataSetName\":\"联动演示-品类销售-源\",\"chartData\":\"[{\\\"value\\\":1048,\\\"name\\\":\\\"华为\\\"},{\\\"value\\\":605,\\\"name\\\":\\\"vivo\\\"},{\\\"value\\\":580,\\\"name\\\":\\\"oppo\\\"},{\\\"value\\\":484,\\\"name\\\":\\\"苹果\\\"},{\\\"value\\\":300,\\\"name\\\":\\\"小米\\\"}]\",\"fieldOption\":[{\"show\":\"Y\",\"label\":\"name\",\"text\":\"name\",\"type\":\"String\",\"value\":\"name\"},{\"show\":\"Y\",\"label\":\"value\",\"text\":\"value\",\"type\":\"String\",\"value\":\"value\"}],\"actionConfig\":{\"operateType\":\"modal\",\"modalName\":\"\",\"url\":\"\"},\"seriesType\":[],\"markLineConfig\":{\"show\":false,\"markLine\":[]},\"dataMapping\":[{\"mapping\":\"name\",\"filed\":\"维度\"},{\"mapping\":\"value\",\"filed\":\"数值\"}],\"dataType\":2,\"query\":[],\"h\":300,\"dataSetApi\":\"https://api.jeecg.com/mock/51/drilling/category_sales\",\"drillData\":[],\"viewLoading\":true,\"url\":\"http://api.jeecg.com/mock/33/chart\",\"dataSetMethod\":\"get\",\"timeOut\":0,\"size\":{\"height\":300},\"dataSetId\":\"1225719143696388096\",\"dataSetType\":\"api\",\"background\":\"#FFFFFF00\",\"w\":450,\"turnConfig\":{\"type\":\"_blank\",\"url\":\"\"},\"linkType\":\"url\",\"linkageConfig\":[],\"dataSetIzAgent\":\"0\",\"option\":{\"yAxis\":{\"axisLabel\":{\"color\":\"#EEF1FA\"},\"splitLine\":{\"lineStyle\":{\"color\":\"#8F8D8D\"},\"show\":false,\"interval\":2},\"yUnit\":\"\"},\"customColor\":[{\"color1\":\"#1e90ff\",\"color\":\"#D0021B\"},{\"color1\":\"#90ee90\",\"color\":\"#4A4A4A\"},{\"color1\":\"#00ced1\",\"color\":\"#00CED1\"},{\"color1\":\"#e2bd84\",\"color\":\"#F8E71C\"},{\"color1\":\"#7a90e0\",\"color\":\"#7A90E0\"},{\"color1\":\"#3ba272\",\"color\":\"#8B572A\"},{\"color1\":\"#2be7ff\",\"color\":\"#D0021B\"},{\"color1\":\"#0a8ada\",\"color\":\"#417505\"},{\"color1\":\"#ffd700\",\"color\":\"#FFD700\"}],\"xAxis\":{\"axisLabel\":{\"color\":\"#EEF1FA\"},\"data\":[],\"axisLine\":{\"lineStyle\":{\"color\":\"#EEF1FA\"}},\"boundaryGap\":false,\"nameTextStyle\":{\"color\":\"#EEF1FA\"}},\"grid\":{\"top\":30,\"left\":0,\"bottom\":18,\"right\":40,\"containLabel\":true},\"series\":[{\"areaStyleOpacity\":0.5,\"areaStyle\":{},\"data\":[],\"label\":{\"position\":\"top\"},\"type\":\"line\"}],\"tooltip\":{\"textStyle\":{\"color\":\"#EEF1FA\"}},\"title\":{\"textAlign\":\"left\",\"show\":true,\"text\":\"面积图\",\"textStyle\":{\"color\":\"#EEF1FA\",\"fontWeight\":\"normal\"},\"subtextStyle\":{\"color\":\"#EEF1FA\"}},\"card\":{\"rightHref\":\"\",\"size\":\"default\",\"extra\":\"\",\"title\":\"\"}}}','admin','2026-06-24 14:26:15',NULL,NULL);
REPLACE INTO `onl_drag_page_comp` (`id`, `parent_id`, `page_Id`, `comp_id`, `component`, `config`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES ('1229647312795160576',NULL,'1228912868522151936',NULL,'JCustomEchart','{\"borderColor\":\"#FFFFFF00\",\"paramOption\":[{\"defaultVal\":\"\",\"label\":\"品类\",\"text\":\"品类\",\"type\":\"string\",\"value\":\"category\"}],\"dataSetName\":\"联动演示-月度趋势-目标1\",\"fieldOption\":[{\"show\":\"Y\",\"label\":\"name\",\"text\":\"name\",\"type\":\"String\",\"value\":\"name\"},{\"show\":\"Y\",\"label\":\"value\",\"text\":\"value\",\"type\":\"Integer\",\"value\":\"value\"}],\"actionConfig\":{\"operateType\":\"modal\",\"modalName\":\"\",\"url\":\"\"},\"seriesType\":[],\"customRenderType\":\"html\",\"customHtmlContent\":\"<!doctype html>\\n<html lang=\\\"zh-CN\\\">\\n\\t<head>\\n\\t\\t<meta charset=\\\"UTF-8\\\" />\\n\\t\\t<title>联动示例</title>\\n\\t\\t<style>\\n\\t\\t\\t* {\\n\\t\\t\\t\\tmargin: 0;\\n\\t\\t\\t\\tpadding: 0;\\n\\t\\t\\t\\tbox-sizing: border-box;\\n\\t\\t\\t}\\n\\t\\t\\tbody {\\n\\t\\t\\t\\tbackground: transparent;\\n\\t\\t\\t\\tfont-family: \'Microsoft YaHei\', sans-serif;\\n\\t\\t\\t\\tpadding: 16px;\\n\\t\\t\\t\\tcolor: #fff;\\n\\t\\t\\t}\\n\\t\\t\\t.title {\\n\\t\\t\\t\\ttext-align: center;\\n\\t\\t\\t\\tfont-size: 16px;\\n\\t\\t\\t\\tfont-weight: bold;\\n\\t\\t\\t\\tletter-spacing: 2px;\\n\\t\\t\\t\\tcolor: #e0e8f0;\\n\\t\\t\\t\\tmargin-bottom: 14px;\\n\\t\\t\\t}\\n\\t\\t\\t.tip {\\n\\t\\t\\t\\ttext-align: center;\\n\\t\\t\\t\\tfont-size: 12px;\\n\\t\\t\\t\\tcolor: #8899aa;\\n\\t\\t\\t\\tmargin-bottom: 14px;\\n\\t\\t\\t}\\n\\t\\t\\t.grid {\\n\\t\\t\\t\\tdisplay: grid;\\n\\t\\t\\t\\tgrid-template-columns: repeat(3, 1fr);\\n\\t\\t\\t\\tgap: 12px;\\n\\t\\t\\t}\\n\\t\\t\\t.cell {\\n\\t\\t\\t\\tposition: relative;\\n\\t\\t\\t\\tborder-radius: 10px;\\n\\t\\t\\t\\tpadding: 18px 12px;\\n\\t\\t\\t\\tcursor: pointer;\\n\\t\\t\\t\\ttransition: all 0.25s;\\n\\t\\t\\t\\tborder: 1px solid rgba(255, 255, 255, 0.12);\\n\\t\