:0 6px 18px rgba(0,0,0,.25);border-color:rgba(255,255,255,.3)}.cell.active{border-color:#ffe066;box-shadow:0 0 22px rgba(255,224,102,.55)}.cell-name{font-size:13px;color:rgba(255,255,255,.85);margin-bottom:8px}.cell-value{font-size:22px;font-weight:bold;color:#fff}.cell-unit{font-size:12px;font-weight:normal;color:rgba(255,255,255,.7);margin-left:2px}.empty{grid-column:1/-1;text-align:center;color:#8899aa;padding:24px;font-size:13px}</style></head><body><div class=\\\"title\\\">钻取</div><div class=\\\"tip\\\">数据来自配置的数据集，前两列分别作为名称和数值</div><div class=\\\"grid\\\" id=\\\"grid\\\"><div class=\\\"empty\\\">等待数据集返回数据...</div></div><script>(function(){var grid=document.getElementById(\\\"grid\\\");var current=null;function render(list){grid.innerHTML=\\\"\\\";if(!list||!list.length){grid.innerHTML=\'<div class=\\\"empty\\\">暂无数据</div>\';return}var keys=Object.keys(list[0]||{});var nameKey=keys[0],valueKey=keys[1];list.slice(0,6).forEach(function(row){var cell=document.createElement(\\\"div\\\");cell.className=\\\"cell\\\";cell.innerHTML=\'<div class=\\\"cell-name\\\">\'+(row[nameKey]!=null?row[nameKey]:\\\"--\\\")+\'</div><div class=\\\"cell-value\\\">\'+(row[valueKey]!=null?row[valueKey]:\\\"--\\\")+\'</div>\';cell.addEventListener(\\\"click\\\",function(){if(current)current.classList.remove(\\\"active\\\");cell.classList.add(\\\"active\\\");current=cell;window.JLink&&window.JLink.drill(row)});grid.appendChild(cell)})}window.JLink&&window.JLink.onData(render)})();</script></body></html>\",\"dataType\":2,\"query\":[],\"h\":300,\"dataSetApi\":\"https://api.jeecg.com/mock/51/drilling/drill_demo?region=${region}\",\"drillData\":[{\"source\":\"name\",\"target\":\"region\"}],\"viewLoading\":true,\"customEchartOption\":\"\",\"url\":\"\",\"dataSetMethod\":\"get\",\"timeOut\":0,\"size\":{\"height\":300},\"dataSetId\":\"1225728165669457920\",\"dataSetType\":\"api\",\"background\":\"#FFFFFF00\",\"w\":450,\"linkType\":\"comp\",\"dataSetIzAgent\":\"0\",\"option\":{\"title\":{\"textAlig