-- MySQL/MariaDB
ALTER TABLE onl_cgform_field MODIFY COLUMN query_def_val VARCHAR(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '查询默认值';


-- 【前端console警告修复】demo演示菜单"Tab带参1/Tab带参2"的 url 是绝对路径且缺少父级":id"参数，注册为真实路由时触发 vue-router 的
update sys_permission set is_route = 0 where id in ('1438115924159881218', '1438116003012796418');

-- ---date:20260721--for:【issues/9787】AI应用增加分享令牌，防止匿名仅凭appId刷额度
ALTER TABLE airag_app
    ADD COLUMN share_token varchar(64) NULL DEFAULT NULL COMMENT '分享令牌（匿名聊天凭证）';

-- 已发布应用回填不可猜测令牌，保证升级后旧匿名链接需带新 token
UPDATE airag_app SET share_token = REPLACE(UUID(), '-', '') WHERE status = 'release' AND (share_token IS NULL OR share_token = '');

CREATE UNIQUE INDEX idx_airag_app_share_token ON airag_app (share_token);

-- ---date:20260805-----for:LHZP-1356 openapi 接口地址 接口描述 和响应字段说明保存没有效果
ALTER TABLE `open_api`
ADD COLUMN `description` varchar(255) NULL COMMENT '接口描述' AFTER `remarks`;

-- ---date:20260814-----for:【LHZP-1099】旅游APP应用，我问开车多长时间，也回复完整的旅游攻略
UPDATE `airag_app`
SET
    `prologue` = '请输入
出发地：
目的地：
出发日期:
交通方式：',
    `msg_num` = 10,
    `preset_question` = '[{"key":1,"sort":1,"descr":"从北京到天津交通方式自驾，需要主要路线和景点","update":true},{"key":2,"sort":2,"descr":"从北京到西安自驾需要多长时间","update":false}]'
WHERE `id` = '1998717610730352641';


